// الفصل الخامس: العبارات الجبرية والمعادلات
import { AR, fmt, rnd, pick, shuf, fmtTime } from './mathkit.js';
import { $, $$, num, lst, mcq, ch, open, fld, calc, exq, fnq, star } from './engine.js';
import { parseList } from './mathkit.js';
import { evalExpr, R, stepsHTML, steps } from './algebra.js';
import { KB, T2, A, MX, r10, estQ, cmpS } from './kit5.js';

const clean = s => String(s).replace(/ـ/g, '');
/** نعوّضُ قيمَ المتغيّراتِ في العبارة */
function subst(expr, V) { let s = clean(expr).replace(/(\d)\s*([ء-ي])/g, '$1×$2').replace(/([ء-ي])\s*\(/g, '$1×(').replace(/\)\s*([ء-ي\d])/g, ')×$1');
  Object.entries(V).forEach(([k, v]) => { s = s.split(clean(k)).join(String(v)); }); return s.replace(/\*/g, '×').replace(/\//g, '÷'); }
const vtxt = V => Object.entries(V).map(([k, v]) => `${k} = ${AR(v)}`).join('، ');
/** قيمةُ عبارةٍ جبريّة */
const evQ = (tag, expr, V, o = {}) => { const s = subst(expr, V), v = r10(evalExpr(clean(expr), Object.fromEntries(Object.entries(V).map(([k, x]) => [clean(k), x]))));
  return num(tag, o.text || `أوجدْ قيمةَ العبارة ${R(clean(expr))} إذا كانت ${vtxt(V)}`, v, { skill: 'eval', sol: o.sol || [`نعوّضُ: ${R(s)}`, stepsHTML(s.replace(/×/g, '*').replace(/÷/g, '/'))], hints: ['ضعِ العددَ مكانَ المتغيّر.', 'تذكّرْ: ٢س تعني ٢ × س، ونبدأُ بما بينَ الأقواس.'], ...o }); };
/** كتابةُ عبارة */
const exQ = (tag, text, v, o = {}) => exq(tag, o.full ? text : `اكتبْ عبارةً جبريّةً لـ: «${text}»`, clean(v), { skill: 'write', sol: [`${R(clean(v))}`, ...(o.why ? [o.why] : [])], hints: ['حدّدِ الكلمةَ التي تدلُّ على العمليّة: (أكثرُ، زائد، مجموع ← +) (أقلُّ، مطروح، الفرق ← −) (أمثال، ضعف، ضرب ← ×) (نصف، مقسوم ← ÷).'], ...o });
/** حلُّ معادلة */
function eqQ(tag, eq, o = {}) { const e = clean(eq), [L, Rr] = e.split('='), vs = (e.match(/[ء-ي]/g) || [])[0];
  let x = null; for (let k = 0; k <= 500; k++) { const env = { [vs]: k }; if (Math.abs(evalExpr(L, env) - evalExpr(Rr, env)) < 1e-9) { x = k; break; } }
  const sv = (L.includes(vs) ? L : Rr).trim(), other = (L.includes(vs) ? Rr : L).trim(), sym = vs === 'ج' ? 'جـ' : vs === 'ه' ? 'هـ' : vs;
  const q = /[ء-ي]\s*\+|\+\s*[ء-ي]/.test(sv) ? 'ما العددُ الذي نضيفُه' : /-\s*[ء-ي]/.test(sv) ? 'ما العددُ الذي نطرحُه' : /[ء-ي]\s*-/.test(sv) ? 'ما العددُ الذي نطرحُ منه' : 'ما العددُ الذي نضربُه';
  return num(tag, o.text || `حُلَّ المعادلةَ وتحقّقْ من صحّةِ الحلّ: ${R(e)}`, x, { skill: /[*×]|\d\s*[ء-ي]/.test(sv) ? 'eqm' : 'eqa', sol: [...(o.pre || []), `فكّرْ: ${q} ليكونَ الناتجُ ${AR(other)}؟`, `${R(subst(sv, { [vs]: x }))} = ${AR(other)} ✓`, `إذن ${sym} = ${AR(x)}`], hints: ['جرّبْ أعدادًا مكانَ المتغيّرِ حتى يتساوى الطرفان، أو استعملِ العمليّةَ العكسيّة.'], ...o }); }
/** جدولُ دالّة */
function ftQ(tag, text, rule, ins, o = {}) { const v = clean(o.v || 'س'); const f = x => r10(evalExpr(clean(rule), { [v]: x }));
  const tb = T2(['المدخلات (' + (o.vn || v) + ')', R(clean(rule)), 'المخرجات'], ins.map(x => [AR(x), '▢', '▢']));
  return fld(tag, text, ins.map(x => [`المخرجةُ عندما ${o.vn || v} = ${AR(x)}`, f(x)]), { skill: 'ftab', html: o.noTable ? '' : tb, sol: ins.map(x => `${R(subst(rule, { [v]: x }))} = ${AR(f(x))}`), hints: ['عوّضْ كلَّ مدخلةٍ في القاعدة.'], ...o }); }
const ruleQ = (tag, ins, outs, ans, o = {}) => exq(tag, o.text || 'اكتبْ قاعدةَ الدالّةِ (بدلالة س) التي تعبّرُ عن العلاقةِ بينَ المدخلاتِ والمخرجات:', clean(ans), { skill: 'rule', html: T2(['المدخلات (س)', 'المخرجات'], ins.map((x, i) => [AR(x), AR(outs[i])])), sol: [`القاعدة: ${R(clean(ans))}`, `تحقّقْ: ${ins.map((x, i) => `${R(subst(ans, { 'س': x }))} = ${AR(outs[i])}`).join(' ، ')}`], hints: ['قارنْ كلَّ مدخلةٍ بمخرجتِها: هل نضيفُ أو نطرحُ أو نضربُ أو نقسم؟'], ...o });

/* ───── نماذجُ الأكوابِ وقطعِ العدّ ───── */
const cup = (x, y) => `<path d="M${x} ${y} h26 l-4 34 h-18z" fill="#cfe9fb" stroke="#4a9fd8" stroke-width="1.5"/><ellipse cx="${x + 13}" cy="${y}" rx="13" ry="3.5" fill="#e9f6ff" stroke="#4a9fd8"/>`;
const cnt = (x, y) => `<circle cx="${x}" cy="${y}" r="8" fill="#f5c842" stroke="#c08a10" stroke-width="1"/>`;
const grid = (n, x0, y0, w) => { let g = ''; const cols = Math.max(1, Math.ceil(n / 5)); for (let i = 0; i < n; i++) g += cnt(x0 + (i % cols) * 20 + (w - cols * 20) / 2 + 10, y0 + Math.floor(i / cols) * 20 + 10); return g; };
/** cups: عددُ الأكواب، k: قطعٌ مع الكوب، op: '+'|'-'|'*'، r: قطعُ الطرفِ الآخر */
export function eqSVG(cups, k, op, r, fill = 0) { const W = 150; let L = '';
  for (let i = 0; i < cups; i++) L += cup(110, 12 + i * 46) + (fill ? [...Array(Math.min(fill, 6))].map((_, j) => cnt(116 + (j % 2) * 14, 24 + i * 46 + Math.floor(j / 2) * 9)).join('') + (fill > 6 ? `<text x="123" y="${i * 46 + 52}" font-size="10" text-anchor="middle">${AR(fill)}</text>` : '') : '');
  if (k) L += `<text x="84" y="44" font-size="22" fill="#333">${op === '-' ? '−' : '+'}</text>` + grid(k, 6, 8, 70);
  const H = Math.max(cups * 46 + 16, Math.ceil(r / Math.max(1, Math.ceil(r / 5))) * 20 + 20, k ? Math.ceil(k / Math.max(1, Math.ceil(k / 5))) * 20 + 20 : 0, 70);
  return `<svg viewBox="0 0 ${2 * W + 40} ${H}" style="max-width:340px;width:100%;direction:ltr"><rect x="1" y="1" width="${W}" height="${H - 2}" rx="8" fill="#fff8e6" stroke="#c9a96a"/><rect x="${W + 39}" y="1" width="${W}" height="${H - 2}" rx="8" fill="#fff8e6" stroke="#c9a96a"/><g transform="translate(${W + 39} 0)">${L}</g><text x="${W + 20}" y="${H / 2 + 8}" font-size="26" text-anchor="middle">=</text>${grid(r, 0, 8, W)}</svg>`; }
function eqTool(el) {
  const T = [['س + ٣ = ٥', 1, 3, '+', 5], ['س − ٤ = ٢', 1, 4, '-', 2], ['ك + ٢ = ٩', 1, 2, '+', 9], ['٢س = ٨', 2, 0, '*', 8], ['٣س = ١٢', 3, 0, '*', 12]];
  let t = 0, f = 0;
  const val = () => { const [, c, k, op] = T[t]; return op === '+' ? f + k : op === '-' ? f - k : c * f; };
  const draw = () => { const [s, c, k, op, r] = T[t], v = val();
    el.innerHTML = `<div class="row">${T.map((x, i) => `<button class="btn sm ${i === t ? '' : 'ghost'}" data-t="${i}">${x[0]}</button>`).join('')}</div>${eqSVG(c, k, op, r, f)}<div class="row c"><button class="btn sm" data-a="m">− قطعة</button><b>في كلِّ كوب: ${AR(f)}</b><button class="btn sm" data-a="p">+ قطعة</button></div><div class="keybox">${op === '-' ? `نأخذُ ${AR(k)} قطعٍ من الكوب فيبقى ${AR(Math.max(0, v))}` : `الطرفُ الأيمنُ فيه ${AR(v)} قطعة`} — والطرفُ الأيسرُ ${AR(r)}: ${v === r ? '<b>✓ متساويان! الحلّ ' + AR(f) + '</b>' : v < r ? 'أضفْ قطعًا' : 'أزلْ قطعًا'}</div>`;
    $$('[data-t]', el).forEach(b => b.onclick = () => { t = +b.dataset.t; f = 0; draw(); }); $('[data-a="p"]', el).onclick = () => { f = Math.min(20, f + 1); if (val() === T[t][4]) star(1); draw(); }; $('[data-a="m"]', el).onclick = () => { f = Math.max(0, f - 1); draw(); }; };
  draw();
}
/** آلةُ الدوالّ */
function machineTool(el) {
  const RL = [['ن − ٤', x => x - 4], ['ن + ٦', x => x + 6], ['٢ن', x => 2 * x], ['٣ن', x => 3 * x], ['ن ÷ ٢', x => x / 2]];
  let r = 0, hist = [];
  const draw = () => { el.innerHTML = `<div class="row">القاعدة: ${RL.map((x, i) => `<button class="btn sm ${i === r ? '' : 'ghost'}" data-r="${i}">${x[0]}</button>`).join('')}</div>
    <div class="row c"><input type="number" class="mi" value="10" style="width:70px"> <b>⟵ مدخلة</b> <span class="dgcard" style="padding:8px 14px">⚙️ ${RL[r][0]}</span> <b>مخرجة ⟵</b> <b class="dgnum mo">؟</b></div><div class="row c"><button class="btn sm">أدخلْ في الآلة</button></div>${hist.length ? T2(['المدخلات (ن)', RL[r][0], 'المخرجات'], hist.map(([a, b]) => [AR(a), '', AR(b)])) : ''}`;
    $$('[data-r]', el).forEach(b => b.onclick = () => { r = +b.dataset.r; hist = []; draw(); });
    $('button.btn.sm:not([data-r])', el).onclick = () => { const a = +$('.mi', el).value; const b = r10(RL[r][1](a)); hist.push([a, b]); hist = hist.slice(-6); draw(); $('.mo', el).textContent = AR(b); }; };
  draw();
}

/* ═════════ المولّدات ═════════ */
const VS = ['س', 'ص', 'ن', 'ك', 'م', 'ع', 'ب'];
const WT = [['أكثرُ من %v بـ %a', '%v+%a'], ['أقلُّ من %v بمقدار %a', '%v-%a'], ['%a مطروحًا منه %v', '%a-%v'], ['مجموعُ %v و%a', '%v+%a'], ['ناتجُ ضربِ %a في %v', '%a%v'], ['%v مقسومًا على %a', '%v/%a'], ['%a مقسومًا على %v', '%a/%v'], ['ضعفُ %v', '2%v'], ['نصفُ %v', '%v/2'], ['%a أمثالِ %v', '%a%v']];
const G = {
  eval: L => { const v = pick(VS), x = rnd(2, L ? 20 : 12), a = rnd(2, 30), t = rnd(0, L ? 5 : 3); const e = [`${v}+${a}`, `${a + x}-${v}`, `${a}${v}`, `${a * x}/${v}`, `${a}×(${v}+${rnd(1, 9)})`, `${a}${v}-${rnd(1, a * x)}`][t]; return evQ('', e, { [v]: x }); },
  write: L => { const v = pick(VS), [w, e] = pick(WT), a = rnd(3, L ? 50 : 20); return exQ('', w.replace(/%v/g, v).replace(/%a/g, AR(a)), e.replace(/%v/g, v).replace(/%a/g, a)); },
  ftab: L => { const t = rnd(0, 3), a = rnd(2, 12), x0 = rnd(1, 10) * (t === 3 ? a : 1); const rule = ['س+' + a, 'س-' + Math.min(a, x0), a + 'س', 'س/' + a][t]; const ins = t === 3 ? [x0, x0 + a, x0 + 2 * a] : [x0, x0 + 1, x0 + 2]; return ftQ('', `أكملْ جدولَ الدالّةِ ذاتِ القاعدة ${R(rule)}`, rule, ins); },
  ftab1: L => { const a = rnd(2, 12), x = rnd(2, 15), t = rnd(0, 2), rule = ['س+' + a, a + 'س', 'س-' + Math.min(a, x)][t], v = r10(evalExpr(rule, { 'س': x })); return num('', `ما المخرجةُ في جدولِ الدالّةِ ذاتِ القاعدة ${R(rule)} عندما تكونُ المدخلة ${AR(x)}؟`, v, { skill: 'ftab', sol: [`${R(subst(rule, { 'س': x }))} = ${AR(v)}`] }); },
  rule1: L => { const a = rnd(2, 9), x0 = rnd(2, 12), t = rnd(0, 2); const ins = [x0, x0 + 1, x0 + 2], f = [x => x + a, x => x * a, x => x - Math.min(a, x0)][t]; const opts = [`س + ${AR(a)}`, `${AR(a)}س`, `س − ${AR(Math.min(a, x0))}`, `س + ${AR(a + 1)}`];
    return { ...mcq('', 'أيُّ قاعدةٍ تمثّلُ جدولَ الدالّةِ المجاور؟', opts, t, { skill: 'rule', sol: [ins.map(x => `${AR(x)} ← ${AR(f(x))}`).join(' ، ')] }), html: T2(['المدخلات (س)', 'المخرجات'], ins.map(x => [AR(x), AR(f(x))])), htmlOpt: true }; },
  rule: L => { const t = rnd(0, 2), a = rnd(2, 12), x0 = rnd(2, 20); const ins = [x0, x0 + 1, x0 + 2, x0 + 3]; const f = [x => x + a, x => x * a, x => x - Math.min(a, x0)][t]; return ruleQ('', ins, ins.map(f), ['س+' + a, a + 'س', 'س-' + Math.min(a, x0)][t]); },
  order: L => { const a = rnd(2, 12), b = rnd(2, 9), c = rnd(2, 9), d = rnd(2, 9); const e = pick([`${a * b + c}-${b}*${c}`.replace(/^/, ''), `${a}+${b}*${c}`, `(${a}+${b})*${c}`, `${a}*${b}+${c}*${d}`, `${b * c * d}/${c}-${d}`, `(${a + b * 2}-${b})*${c}`]); return calc('', e, { skill: 'order' }); },
  eqa: L => { const v = pick(VS), x = rnd(1, L ? 50 : 20), a = rnd(1, L ? 40 : 15), t = rnd(0, 3); return eqQ('', [`${v}+${a}=${x + a}`, `${a}+${v}=${x + a}`, `${v}-${a}=${x}`, `${x + a}-${v}=${a}`][t]); },
  eqm: L => { const v = pick(VS), x = rnd(1, 12), a = rnd(2, L ? 12 : 9); return eqQ('', Math.random() < .5 ? `${a}${v}=${a * x}` : `${a * x}=${a}${v}`); },
  simpler: L => { const n = rnd(2, 5), c = rnd(2, 4) * n, h = pick([2, 3]), N = rnd(3, 8), H = h * rnd(2, 4); const per = c / n / h; return num('', `يصنعُ ${AR(n)} خبّازينَ ${AR(c)} كعكةً كلَّ ${AR(h)} ساعات. كم كعكةً يصنعُها ${AR(N)} خبّازينَ في ${AR(H)} ساعات، إذا كان كلٌّ منهم يُنتجُ العددَ نفسَه في الساعة؟`, per * N * H, { skill: 'simpler', sol: [`الخبّازُ الواحدُ: ${AR(c)} ÷ ${AR(n)} = ${AR(c / n)} كعكاتٍ كلَّ ${AR(h)} ساعات`, `في ${AR(H)} ساعات: ${AR(c / n)} × ${AR(H / h)} = ${AR(c / n * H / h)} كعكة`, `${AR(N)} خبّازين: ${AR(N)} × ${AR(c / n * H / h)} = ${AR(per * N * H)}`] }); },
};
const GN = { eval: 'إيجاد قيمة عبارة جبرية', write: 'كتابة عبارة جبرية', ftab: 'إكمال جدول دالة', ftab1: 'مخرجة دالة', rule1: 'اختيار قاعدة الدالة', rule: 'إيجاد قاعدة الدالة', order: 'ترتيب العمليات', eqa: 'حل معادلات الجمع والطرح', eqm: 'حل معادلات الضرب', simpler: 'حل مسألة أبسط' };

const units = {};
const W1 = s => calc('', s.e, { text: `اكتبْ «${s.w}» بالصيغةِ الرمزيّة، ثم أوجدِ الناتج.` });
/* ═════════ التهيئة ═════════ */
units.t5r = { kind: 'test', title: 'التهيئة', idea: 'أتأكّدُ من المهاراتِ السابقة: الجمع، والضرب، والصيغةُ اللفظيّةُ للعمليّات.',
  intro: [{ h: '🎢 الفكرةُ العامّة: ما العبارةُ الجبريّة؟', p: 140, html: '<p><b>العبارةُ الجبريّة:</b> مجموعةٌ من المتغيّراتِ والأعدادِ تربطُها عمليّةٌ واحدةٌ على الأقلّ، مثل: <b>س + ٩</b> (س متغيّر، + عمليّة، ٩ عدد).</p><p><b>مثال:</b> يبلغُ ارتفاعُ سكّةِ قطارِ الألعابِ في مدينةِ الألعاب ٣٥ مترًا، وقد قرّرَ مديرُ المدينةِ أن يشتريَ سكّةَ قطارٍ جديدة، يزيدُ ارتفاعُها بمقدارِ س مترًا على ارتفاعِ السكّةِ الحاليّة. استعملِ العبارة ٣٥ + س لإيجادِ ارتفاعِ السكّةِ الجديدة.</p><p><b>ماذا أتعلّمُ في هذا الفصل؟</b> كتابةَ عباراتٍ جبريّةٍ وإيجادَ قيمِها، وتمثيلَ دوالَّ باستعمالِ آلاتِ الدوالّ، وإكمالَ جداولِ الدوالّ، وحلَّ مسائلَ باستعمالِ خطّةِ «حلُّ مسألةٍ أبسط»، وكتابةَ معادلاتِ الجمعِ والطرحِ والضربِ وحلَّها.</p>' + KB('المفردات', 'المتغيّر ، العبارةُ الجبريّة ، حسابُ قيمة ، الدالّة ، ترتيبُ العمليّات') }],
  ex: [['🧮 أجبْ عن الأسئلةِ الآتية', 142, [calc('١', '6+3'), calc('٢', '9+8'), calc('٣', '12+4'), calc('٤', '19+2'), calc('٥', '17+18'), calc('٦', '24+35'),
    num('٧', 'لدى فهدٍ ٢٥ سيّارةً لعبة. إذا اشترى ٧ سيّاراتٍ أخرى، فكم سيّارةً سيصبحُ لديه؟', 32, { sol: ['٢٥ + ٧ = ٣٢'] }),
    num('٨', 'القياس: تستعملُ هندُ ملعقتينِ من الزبيبِ لصنعِ عجينةِ كعكةٍ واحدة. كم ملعقةً من الزبيبِ تستعملُ إذا أرادتْ أن تصنعَ ٣ كعكات؟', 6, { sol: ['٣ × ٢ = ٦ ملاعق'] }),
    calc('٩', '5*2'), calc('١٠', '3*4'), calc('١١', '7*5'), calc('١٢', '11*3'), calc('١٣', '15*2'), calc('١٤', '20*3'),
    num('١٥', 'أوجدْ ثمنَ ٦ بطاقاتِ تهنئة، إذا كان ثمنُ البطاقةِ ريالين.', 12, { unit: 'ريالًا', sol: ['٦ × ٢ = ١٢ ريالًا'] }),
    num('١٦', 'يوجدُ لدينا ثلاثُ علبٍ فيها العددُ نفسُه من قطعِ الشوكولاتة، أكلَ أخي قطعةً واحدةً من إحدى العلب، فبقيَ فيها ٧ قطع. كم قطعةَ شوكولاتةٍ كانتْ في العلبِ الثلاث؟', 24, { sol: ['كان في العلبةِ الواحدة: ٧ + ١ = ٨ قطع', 'في العلبِ الثلاث: ٣ × ٨ = ٢٤ قطعة'] }),
    W1({ w: 'خمسة عشر ناقص ستّة', e: '15-6' }), W1({ w: 'ستّة زائد أربعة', e: '6+4' }), W1({ w: 'عشرة مقسومًا على خمسة', e: '10/5' }), W1({ w: 'ثمانية ضرب ثلاثة', e: '8*3' })].map((p, i) => i >= 16 ? { ...p, tag: AR(i + 1) } : p)]] };

/* ═════════ ٥-١ عباراتُ الجمعِ والطرحِ الجبريّة ═════════ */
